from graphviz import Digraph# Create a new directed graphmindmap = Digraph(comment='Mind Map Example', format='png')mindmap.attr(rankdir='LR', size='8,5')mindmap.attr('node', shape='ellipse', style='filled', color='lightblue2', fontname='Helvetica')# Central topicmindmap.node('A', 'Main Topic')# First layer of subtopicssubtopics = {    'B': 'Idea 1',    'C': 'Idea 2',    'D': 'Idea 3'}for node_id, label in subtopics.items():    mindmap.node(node_id, label)    mindmap.edge('A', node_id)# Second layer (details or examples)mindmap.node('B1', 'Detail A')mindmap.edge('B', 'B1')mindmap.node('C1', 'Example X')mindmap.node('C2', 'Example Y')mindmap.edge('C', 'C1')mindmap.edge('C', 'C2')mindmap.node('D1', 'Aspect M')mindmap.node('D2', 'Aspect N')mindmap.edge('D', 'D1')mindmap.edge('D', 'D2')# Render the mind map to a filemindmap.render('mindmap_example', view=True)## write .gv.txt versionwith open('mindmap_example2.gv.txt', 'w') as f:    f.write(mindmap.source)    mindmap.render('mindmap_example2.gv.txt', view=False)mindmap.render('mindmap_example3.gv.txt', view=False)